def is_valid_tic_tac_toe_counts(board):
    if len(board) != 3:
        return False
    for row in board:
        if len(row) != 3:
            return False
    x_count = o_count = 0
    for row in board:
        for c in row:
            if c == 'X':
                x_count += 1
            elif c == 'O':
                o_count += 1
            elif c != ' ':
                return False
    return x_count == o_count or x_count == o_count + 1

def days_until_next_birthday(birth_md, today_ymd):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim_list(y):
        return [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    def doy(y, m, d):
        return sum(dim_list(y)[:m - 1]) + d
    def days_in_year(y):
        return 366 if is_leap(y) else 365
    m, d = birth_md
    y, tm, td = today_ymd
    today_doy = doy(y, tm, td)
    bday_doy = doy(y, m, d)
