def compress_runs_min_length(s, min_run):
    if not s:
        return ""
    result = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        run_len = j - i
        if run_len >= min_run:
            result.append(s[i] + str(run_len))
        else:
            result.append(s[i] * run_len)
        i = j
    return "".join(result)

